import{z as o,x as B,o as r,c as m,q as i,j as n,D as t,d as E,s,S as A,b as e}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"完备市场与唯一测度","description":"","frontmatter":{"title":"完备市场与唯一测度","date":"2026-09-10T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/complete-unique-measure.md","filePath":"quant/complete-unique-measure.md","lastUpdated":1791413859000}'),d={name:"quant/complete-unique-measure.md"};function h(p,a,u,c,D,f){const l=B("Mermaid");return r(),m("div",null,[a[2]||(a[2]=i('<h1 id="完备市场与唯一测度" tabindex="-1">完备市场与唯一测度 <a class="header-anchor" href="#完备市场与唯一测度" aria-label="Permalink to &quot;完备市场与唯一测度&quot;">​</a></h1><div class="epigraph"><p>市场完备当且仅当等价鞅测度唯一。唯一的 $Q$ 给出每个未定权益的唯一无套利价格，并保证可复制。</p><footer>—— 据 Harrison and Pliska, 1981；Delbaen and Schachermayer, The Mathematics of Arbitrage, 2006；Shreve, Stochastic Calculus for Finance II, 第 5 章整理</footer></div><p>上一课<a href="/quant/risk-neutral-measure">风险中性测度</a>用第一基本定理给出「存在 \\(Q\\)」。缺口是：存在不等于唯一。许多 \\(Q\\) 意味着同一支付可以对应一个价格区间。本课把第二基本定理钉成可用形式：完备 \\(\\Leftrightarrow\\) \\(Q\\) 唯一，并指出 Black–Scholes 市场为何落在这一侧。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一个布朗驱动一个可交易标的（加货币市场）时，\\(\\theta=(\\mu-r)/\\sigma\\) 被方程钉死，\\(Q\\) 唯一。两个独立布朗只驱动一个 \\(S\\) 时，\\(\\theta\\) 有一个自由分量，\\(Q\\) 有一族。缺口是给「每个 \\(\\mathcal F_T\\)-可测支付都能用可容许策略复制」起个名字——完备——并把它和唯一 \\(Q\\) 焊在一起。没有这条，后课写「BSM 价格」会不知道凭什么是一个数而不是一段。</p><p>可复制意味着存在 \\(\\Delta\\)，使终值几乎必然等于 \\(H\\)。唯一 \\(Q\\) 保证所有无套利价格重合；完备保证这个价格真能靠交易达到，而不只是期望。</p><p><span class="marginnote">「完备」翻译成大白话：市场上任何一种「按未来状态付钱」的合约，都能用现有可交易资产精确拼出一个复制品。可以想象成乐高——股票加债券这些基础块方向够全，就能拼出任何目标形状；缺一个方向，就有拼不出来的支付，价格就只能报一个区间。</span></p><h3 id="完备不是「市场流动性好」" tabindex="-1">完备不是「市场流动性好」 <a class="header-anchor" href="#完备不是「市场流动性好」" aria-label="Permalink to &quot;完备不是「市场流动性好」&quot;">​</a></h3><p>完备是生成的未定权益空间是否等于 \\(L^2(\\mathcal F_T)\\)（或合适的可积类），不是买卖价差小。限价簿厚不厚是微观结构，本课程不重写。这里只数独立噪声源与可交易风险源的个数是否匹配。</p><p><span class="marginnote">鞅表示：一个布朗的可积鞅都能写成 \\(\\int\\phi\\,\\mathrm d W^Q\\)。有交易的 \\(S\\) 把 \\(\\mathrm d W^Q\\) 变成 \\(\\mathrm d S\\)，于是表示变成复制。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>第二基本定理（连续时间、技术条件下）：无套利市场完备 \\(\\Leftrightarrow\\) 等价鞅测度唯一。Black–Scholes：一维 GBM + 常数 \\(r\\)，噪声维数等于可交易风险维数，\\(Q\\) 唯一，欧式 \\(H=g(S_T)\\) 可复制。多维：若波动率矩阵在交易资产上可逆，同样唯一。不可逆——多余的布朗或不可交易的随机波动——则不完备。计数规则极简：独立噪声个数减去可交易风险源个数，等于 \\(Q\\) 的自由度数。</p><p>价格公式在完备时不依赖投资者偏好：谁来定价都得报 \\(\\mathrm e^{-rT}\\mathbb E_Q[H]\\)，否则可被复制策略套利。这是后课 PDE、delta 对冲共用同一个数的原因。</p><p><span class="marginnote">拿计数规则代个数字：随机波动率模型里有两个独立布朗（一个驱动股价、一个驱动波动率），但能交易的只有股票这一只——噪声 2 维、可交易风险 1 维，多出的 1 维自由度让 \\(Q\\) 变成一族。初学者容易以为多一个随机参数只是校准麻烦，实际上它让「唯一无套利价格」这个定理结论失效，期权价格只能给区间。</span></p>',14)),(r(),n(A,null,{default:t(()=>[s(l,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20EXIST%5B%22%E5%AD%98%E5%9C%A8%20Q%EF%BC%9A%E6%97%A0%E5%A5%97%E5%88%A9%22%5D%20--%3E%20UNIQUE%5B%22Q%20%E5%94%AF%E4%B8%80%22%5D%0A%20%20UNIQUE%20--%3E%20COMP%5B%22%E5%AE%8C%E5%A4%87%EF%BC%9A%E6%AF%8F%E4%B8%AA%20H%20%E5%8F%AF%E5%A4%8D%E5%88%B6%22%5D%0A%20%20COMP%20--%3E%20PRICE%5B%22%E5%94%AF%E4%B8%80%E4%BB%B7%E6%A0%BC%22%5D%0A%20%20UNIQUE%20--%3E%20INC%5B%22%E4%B8%8D%E5%94%AF%E4%B8%80%E5%88%99%E4%B8%8B%E4%B8%80%E8%AF%BE%E4%B8%8D%E5%85%A8%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"鞅表示定理把 \\(Q\\) 下的平方可积鞅写成对 \\(W^Q\\) 的积分。若每个 \\(W^Q\\) 分量都能被某个可交易资产的 \\(\\mathrm d S\\) 对冲掉，积分变成交易策略，任意合适的 \\(\\mathcal F_T\\) 支付都能达到。若有一个 \\(W\\) 分量进不了任何 \\(\\mathrm d S\\)，表示里的那一项无法交易，对应的密度扰动给出另一个等价鞅测度：在不可对冲方向上倾斜路径权重，贴现可交易资产仍然走平。唯一性失败与不可复制是同一件事的两面。因此「BSM 给出一个数」不是计算方便，是维数匹配的定理结论。",-1)),a[5]||(a[5]=e("p",null,"离散二叉树是完备的有限维原型：每步两个分支、一个股票加债券，恰可复制。三叉树同一步两个以上分支，立刻不完备。连续极限继承这个计数。",-1)),a[6]||(a[6]=e("p",null,[e("span",{class:"marginnote"},"用二叉树代一遍数：一步之后股票有两个可能价格，组合里有一只股票和一份债券，两个分支给两条方程，恰好解出两个持仓权重——复制唯一。换成三叉树，三个分支三条方程、还是两个未知量，多出的那条方程就是无法对冲的自由度，这正是「三叉树不完备」的算术内容。")],-1)),(r(),n(A,null,{default:t(()=>[s(l,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20N%5B%22%E7%8B%AC%E7%AB%8B%E5%99%AA%E5%A3%B0%E6%BA%90%E4%B8%AA%E6%95%B0%22%5D%20--%3E%20M%7B%22%E4%B8%8E%E5%8F%AF%E4%BA%A4%E6%98%93%E9%A3%8E%E9%99%A9%E6%BA%90%E6%AF%94%E8%BE%83%22%7D%0A%20%20T%5B%22%E5%8F%AF%E4%BA%A4%E6%98%93%E9%A3%8E%E9%99%A9%E6%BA%90%E4%B8%AA%E6%95%B0%22%5D%20--%3E%20M%0A%20%20M%20--%3E%7C%22%E7%9B%B8%E7%AD%89%22%7C%20U%5B%22Q%20%E5%94%AF%E4%B8%80%22%5D%0A%20%20M%20--%3E%7C%22%E5%99%AA%E5%A3%B0%E6%9B%B4%E5%A4%9A%22%7C%20F%5B%22Q%20%E6%9C%89%E4%B8%80%E6%97%8F%22%5D%0A%20%20U%20--%3E%20C%5B%22%E5%AE%8C%E5%A4%87%EF%BC%9A%E6%94%AF%E4%BB%98%E5%8F%AF%E5%A4%8D%E5%88%B6%22%5D%0A%20%20F%20--%3E%20I%5B%22%E4%B8%8D%E5%AE%8C%E5%A4%87%EF%BC%9A%E4%BB%B7%E6%A0%BC%E6%88%90%E5%8C%BA%E9%97%B4%22%5D%0A%20%20C%20--%3E%20P%5B%22%E6%8A%A5%E4%BB%B7%20e%5E-rT%20E_Q%20H%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=i('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 Delbaen–Schachermayer 的 NFLVR 与 \\(\\sigma\\)-鞅测度写全。跳跃、随机波动作为不完备的例子只点名，机制放下一课。后课默认：BSM 市场完备，\\(Q\\) 唯一，欧式支付有唯一无套利价。维数一旦失配，不要再把单一 Black 价格当成定理。下一课<a href="/quant/incomplete-market">不全市场</a>处理多个 \\(Q\\) 时价格变成区间。BSM 主干仍走本课的唯一侧。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>完备 \\(\\Leftrightarrow\\) 等价鞅测度唯一（第二基本定理）。</li><li>噪声维数与可交易风险维数匹配时 \\(Q\\) 唯一。</li><li>唯一价格来自可复制，不是来自偏好。</li><li>鞅表示把 \\(Q\\)-期望变成对冲积分。</li><li>二叉树完备、三叉树不完备，计数与连续情形相同。</li><li>出处：Harrison–Pliska 1981；Shreve SDE II 第 5 章。</li></ul>',4))])}const Q=o(d,[["render",h]]);export{F as __pageData,Q as default};
